"use client";
import { useEffect, useMemo, useRef, useState, useSyncExternalStore, type FormEvent, type ReactNode } from "react";
import { ArrowRight, BookOpen, Check, CheckCheck, ChevronRight, ClipboardCheck, Copy, Download, Eye, FileText, GraduationCap, Heart, KeyRound, MessageCircle, Pencil, Plus, ShieldCheck, Sparkles, Target, Trash2, Users, Volume2, X } from "lucide-react";
import { worlds, type Activity, type Question } from "@/lib/content";
import { activityCatalog } from "@/lib/activity-catalog";
import ActivityBank from "./ActivityBank";
import { deriveStudentProgress, getWorldStatus, getDiagnosticResult } from "@/lib/pedagogy";
import type { ApiResult, PlatformAction, PlatformData, Student, Submission } from "@/lib/types";
import "./educator.css";
import "./educator-guidance.css";
import { getEducatorJourney, type EducatorNextAction, type EducatorStepId } from "@/lib/educator-journey";
type Props = { data: PlatformData; onAction: (action: PlatformAction) => Promise<ApiResult>; section: string; onPlay: (activity: Activity) => void; onNavigate?: (section: string) => void };
type Modal = { kind: "class"; id?: string } | { kind: "student"; id?: string; classId?: string } | { kind: "assign"; activityId?: string } | { kind: "note"; studentId: string; intervention?: boolean; initial?: string } | { kind: "account" } | { kind: "replace-code"; studentId: string } | { kind: "editor" } | { kind: "confirm"; title: string; text: string; action: PlatformAction } | { kind: "code"; title: string; code: string };
type DraftQuestion = { id: string; type: Question["type"]; prompt: string; stimulus: string; optionsText: string; matchesText: string; answerText: string; explanation: string; visual?: string; audioText?: string; worldId?: number };
type Draft = { id?: string; title: string; description: string; worldId: number; skill: string; durationMinutes: number; xp: number; questions: DraftQuestion[] };
const lines = (text: string) => text.split("\n").map(item => item.trim()).filter(Boolean);
function QuestionAnswerEditor({ question, onChange }: { question: DraftQuestion; onChange: (patch: Partial<DraftQuestion>) => void }) {
  const options = lines(question.optionsText);
  if (question.type === "choice") return <label>Resposta correta<select value={question.answerText} onChange={event => onChange({ answerText: event.target.value })}><option value="">Selecione a resposta</option>{options.map((option, index) => <option key={index} value={option}>{option}</option>)}</select></label>;
  if (question.type === "order") return <label>Ordem correta — separe com |<input value={question.answerText} onChange={event => onChange({ answerText: event.target.value })} placeholder="BO | LA" /><small>Inclua todas as opções na sequência esperada.</small></label>;
  if (question.type === "multi") {
    const answers = question.answerText.split("|").map(answer => answer.trim()).filter(Boolean);
    return <fieldset className="ed-answer-selector"><legend>Marque todas as respostas corretas</legend>{options.length ? options.map((option, index) => <label key={index}><input type="checkbox" checked={answers.includes(option)} onChange={event => onChange({ answerText: (event.target.checked ? [...answers, option] : answers.filter(answer => answer !== option)).join(" | ") })} /><span>{option}</span></label>) : <p>Adicione opções para definir o gabarito.</p>}</fieldset>;
  }
  const matches = lines(question.matchesText);
  const answers = question.answerText.split("|").map(answer => answer.trim());
  return <><label>Coluna direita — um item por linha<textarea rows={4} value={question.matchesText} onChange={event => onChange({ matchesText: event.target.value })} placeholder={"Abelha\nBola\nCasa"} /><small>Use a mesma quantidade nas duas colunas, sem repetir itens.</small></label><fieldset className="ed-answer-selector ed-span-full"><legend>Gabarito dos pares</legend>{options.length ? options.map((option, index) => <label key={index}><span>{option}</span><select value={answers[index] || ""} onChange={event => { const next = options.map((_, answerIndex) => answers[answerIndex] || ""); next[index] = event.target.value; onChange({ answerText: next.join(" | ") }); }}><option value="">Escolha o par</option>{matches.map((match, matchIndex) => <option key={matchIndex} value={match}>{match}</option>)}</select></label>) : <p>Adicione os itens da coluna esquerda para criar as associações.</p>}</fieldset></>;
}
const blankQuestion = (): DraftQuestion => ({ id: `q-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`, type: "choice", prompt: "", stimulus: "", optionsText: "", matchesText: "", answerText: "", explanation: "" });
const blankDraft = (): Draft => ({ title: "", description: "", worldId: 1, skill: "Consciência fonológica", durationMinutes: 5, xp: 30, questions: [blankQuestion()] });
const date = (value: string) => new Date(value).toLocaleDateString("pt-BR", { day: "2-digit", month: "short" });
const average = (rows: Submission[]) => rows.length ? Math.round(rows.reduce((sum, row) => sum + row.score, 0) / rows.length) : null;
const percent = (value: number | null) => value === null ? "—" : `${value}%`;
const avatar = (student: Student) => student.avatar || "🦊";
const csvCell = (value: string | number) => { let text = String(value); if (/^[\s]*[=+@\-\t\r]/.test(text)) text = `'${text}`; return `"${text.replace(/"/g, '""')}"`; };
const field = (form: FormData, name: string) => String(form.get(name) || "").trim();

const favoriteEvent = "letria-favorites-changed";
function subscribeFavorites(callback: () => void) {
  window.addEventListener("storage", callback);
  window.addEventListener(favoriteEvent, callback);
  return () => { window.removeEventListener("storage", callback); window.removeEventListener(favoriteEvent, callback); };
}
function favoriteSnapshot(key: string) { try { return localStorage.getItem(key) || "[]"; } catch { return "[]"; } }
function Empty({ icon = <BookOpen size={28} />, title, text, children }: { icon?: ReactNode; title: string; text: string; children?: ReactNode }) { return <div className="ed-empty"><div className="ed-empty-icon">{icon}</div><h3>{title}</h3><p>{text}</p>{children}</div>; }
function ProgressBar({ value, mint = false }: { value: number; mint?: boolean }) { return <div className={`ed-progress ${mint ? "mint" : ""}`} aria-label={`${value}%`}><span style={{ width: `${Math.max(0, Math.min(100, value))}%` }} /></div>; }
export default function Educator(props: Props) {
  return <EducatorView key={`${props.data.session.userId}:${props.data.session.role}:${props.section}`} {...props} />;
}
function EducatorView({ data, onAction, section, onPlay, onNavigate }: Props) {
  const [classId, setClassId] = useState(""); const [studentId, setStudentId] = useState("");
  const [modal, setModal] = useState<Modal | null>(null); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(""); const [error, setError] = useState("");
  const [accountRole, setAccountRole] = useState<"teacher" | "guardian">("teacher");
  const [draft, setDraft] = useState<Draft>(blankDraft); const [previewEditor, setPreviewEditor] = useState(false); const [reportNote, setReportNote] = useState(""); const dialogRef = useRef<HTMLDivElement>(null);
  const favoritesKey = `letria-favorite-activities:${data.session.userId}`;
  const favoritesJson = useSyncExternalStore(subscribeFavorites, () => favoriteSnapshot(favoritesKey), () => "[]");
  const favorites = useMemo<string[]>(() => { try { const values: unknown = JSON.parse(favoritesJson); return Array.isArray(values) ? values.filter((value): value is string => typeof value === "string") : []; } catch { return []; } }, [favoritesJson]);
  const isGuardian = data.session.role === "guardian";
  const journey = getEducatorJourney(data, classId);
  const allActivities = useMemo(() => [...activityCatalog, ...data.customActivities.map(activity => ({ ...activity } as Activity))], [data.customActivities]);
  const progressByStudent = useMemo(() => new Map(data.students.map(student => [student.id, deriveStudentProgress(data.submissions.filter(row => row.studentId === student.id))])), [data.students, data.submissions]);
  const activityById = useMemo(() => new Map(allActivities.map(activity => [activity.id, activity])), [allActivities]);
  const filteredStudents = data.students.filter(student => (!classId || student.classroomId === classId) && (section !== "reports" || !studentId || student.id === studentId));
  const scopedSubmissions = data.submissions.filter(row => filteredStudents.some(student => student.id === row.studentId)); const scopedAverage = average(scopedSubmissions);
  const selectedStudent = data.students.find(student => student.id === studentId); const selectedClass = data.classrooms.find(classroom => classroom.id === classId);
  const worldName = (id: number) => worlds.find(world => world.id === id)?.title || `Mundo ${id}`; const studentRows = (id: string) => data.submissions.filter(row => row.studentId === id);
  const activityTitle = (id: string) => activityById.get(id)?.title || (id === "diagnostic" ? "Diagnóstico inicial" : "Atividade arquivada");
  const recent = [...scopedSubmissions].sort((a, b) => b.completedAt.localeCompare(a.completedAt));
  const pendingLearners = filteredStudents.map(student => ({ student, rows: studentRows(student.id), reviewWorld: worlds.find(world => getWorldStatus(progressByStudent.get(student.id)!, world.id).status === "review") })).filter(item => item.reviewWorld).sort((a, b) => (average(a.rows) ?? 0) - (average(b.rows) ?? 0));
  const successful = scopedSubmissions.filter(row => row.score >= 80).length; const activeLearners = new Set(scopedSubmissions.map(row => row.studentId)).size;

  useEffect(() => {
    if (!modal) return; const timer = window.setTimeout(() => dialogRef.current?.querySelector<HTMLElement>("input, select, textarea, button")?.focus(), 20);
    const onKey = (event: KeyboardEvent) => { if (event.key === "Escape" && !busy) setModal(null); if (event.key === "Tab") { const elements = [...(dialogRef.current?.querySelectorAll<HTMLElement>('button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), a[href]') || [])].filter(element => element.offsetParent !== null); const first = elements[0]; const last = elements[elements.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); } if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); } } };
    document.addEventListener("keydown", onKey); return () => { window.clearTimeout(timer); document.removeEventListener("keydown", onKey); };
  }, [modal, busy]);
  async function execute(action: PlatformAction, success?: string) { setBusy(true); setError(""); try { const result = await onAction(action); if (!result.ok) throw new Error(result.error || "Não foi possível salvar."); if (success) {
      const preparation = result.voicePreparation;
      setMessage(success + (preparation === 'queued' ? ' A narração está sendo preparada em segundo plano.'
        : preparation === 'partial' ? ' Parte da narração entrou na fila; publique novamente para preparar o restante.'
          : preparation === 'unavailable' ? ' A narração não entrou na fila agora. Publique novamente quando a voz estiver disponível.' : ''));
    } return result; } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível concluir. Tente novamente."); return null; } finally { setBusy(false); } }
  function changeClass(next: string) { setClassId(next); setStudentId(""); setReportNote(""); }
  function open(next: Modal) { setError(""); setMessage(""); if (next.kind === "account") setAccountRole("teacher"); setModal(next); }
  function followJourney(action: EducatorNextAction) {
    if (action.kind === "account") open({ kind: "account" });
    else if (action.kind === "class") open({ kind: "class", id: action.id });
    else if (action.kind === "student") open({ kind: "student", id: action.id, classId: action.classId });
    else if (onNavigate) onNavigate(action.section);
    else if (action.section === "activities") open({ kind: "assign" });
  }
  function chooseJourneyStep(id: EducatorStepId) {
    if (id === "reports") { onNavigate?.("reports"); return; }
    if (id === journey.current) { followJourney(journey.action); return; }
    if (id === "accounts") { open({ kind: "account" }); return; }
    if (id === "classes") { if (data.classrooms.length && onNavigate) onNavigate("classes"); else open({ kind: "class" }); return; }
    if (id === "students") { open(data.classrooms.length ? { kind: "student", classId: classId || data.classrooms[0].id } : { kind: "class" }); return; }
    if (id === "activities") { if (onNavigate) onNavigate("activities"); else open({ kind: "assign" }); return; }
    onNavigate?.("reports");
  }
  function journeyPanel() {
    return <section className="ed-journey panel" aria-labelledby="ed-next-step-title">
      <div className="ed-next-step"><span className="ed-stat-icon lilac" aria-hidden="true"><BookOpen size={27} /></span><div><span className="eyebrow">SEU PRÓXIMO PASSO</span><h2 id="ed-next-step-title">{journey.title}</h2><p>{journey.description}</p><button className="btn btn-primary" disabled={busy} onClick={() => followJourney(journey.action)}>{journey.button}<ArrowRight size={17} /></button></div></div>
      <div className="ed-journey-heading"><h3>{data.session.role === "admin" ? "Organize a escola, um passo de cada vez" : "Da primeira turma ao acompanhamento"}</h3><p>Você pode voltar a qualquer etapa quando precisar.</p></div>
      <ol className="ed-journey-steps">{journey.steps.map((step, index) => <li key={step.id} className={step.id === journey.current ? "current" : step.complete ? "complete" : ""}><button disabled={busy} aria-current={step.id === journey.current ? "step" : undefined} onClick={() => chooseJourneyStep(step.id)}><span className="ed-step-number" aria-hidden="true">{step.complete ? <Check size={17} /> : index + 1}</span><span><strong>{step.label}</strong><small>{step.detail}</small>{step.id === journey.current && <span className="ed-step-status">Próximo passo</span>}</span></button></li>)}</ol>
    </section>;
  }
  function editActivity(activity?: Activity, asTemplate = false) {
    setDraft(activity ? { ...(asTemplate ? {} : { id: activity.id }), title: asTemplate ? `Cópia de ${activity.title}`.slice(0, 100) : activity.title, description: activity.description, worldId: activity.worldId, skill: activity.skill, durationMinutes: activity.durationMinutes, xp: activity.xp, questions: activity.questions.map(question => ({ id: question.id, type: question.type, prompt: question.prompt, stimulus: question.stimulus || "", optionsText: question.options.join("\n"), matchesText: question.matches?.join("\n") || "", answerText: Array.isArray(question.answer) ? question.answer.join(" | ") : question.answer, explanation: question.explanation, visual: question.visual, audioText: question.audioText, worldId: question.worldId })) } : blankDraft());
    setPreviewEditor(false); open({ kind: "editor" });
  }
  function toggleFavorite(id: string) { const next = favorites.includes(id) ? favorites.filter(value => value !== id) : [...favorites, id]; try { localStorage.setItem(favoritesKey, JSON.stringify(next)); window.dispatchEvent(new Event(favoriteEvent)); } catch { setError("Não foi possível salvar favoritas neste dispositivo."); } }
  async function accessCode(student: Student) { const result = await execute({ action: "resetStudentCode", studentId: student.id }); if (result?.accessCode) open({ kind: "code", title: `Acesso de ${student.name.split(" ")[0]}`, code: result.accessCode }); }
  async function submitModal(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (!modal) return; const form = new FormData(event.currentTarget); let action: PlatformAction | null = null;
    if (modal.kind === "class") action = modal.id ? { action: "updateClassroom", id: modal.id, name: field(form, "name"), grade: field(form, "grade"), ...(data.session.role === "admin" ? { teacherUserId: field(form, "teacherUserId") || null } : {}) } : { action: "createClassroom", name: field(form, "name"), grade: field(form, "grade"), teacherName: data.session.name, ...(data.session.role === "admin" ? { teacherUserId: field(form, "teacherUserId") || null } : {}) };
    if (modal.kind === "student") action = modal.id ? { action: "updateStudent", id: modal.id, name: field(form, "name"), classroomId: field(form, "classroomId"), grade: field(form, "grade"), avatar: field(form, "avatar") } : { action: "createStudent", name: field(form, "name"), classroomId: field(form, "classroomId"), grade: field(form, "grade"), avatar: field(form, "avatar") };
    if (modal.kind === "assign") action = { action: "assignActivity", classroomId: field(form, "classroomId"), activityId: field(form, "activityId"), dueDate: field(form, "dueDate"), title: field(form, "title") };
    if (modal.kind === "note") action = { action: "addNote", studentId: modal.studentId, text: field(form, "text"), type: modal.intervention ? "intervention" : "observation" };
    if (modal.kind === "account") action = { action: "createUser", name: field(form, "name"), email: field(form, "email"), password: String(form.get("password") || ""), role: field(form, "role") as "teacher" | "guardian", studentId: field(form, "studentId") || undefined };
    if (!action) return; const result = await execute(action, "Tudo certo! Alterações salvas."); if (result) { if (result.accessCode) setModal({ kind: "code", title: `Acesso de ${field(form, "name").split(" ")[0]}`, code: result.accessCode }); else setModal(null); }
  }
  async function saveDraft() {
    const questions: Question[] = draft.questions.map(question => ({ id: question.id, type: question.type, prompt: question.prompt.trim(), stimulus: question.stimulus.trim(), options: lines(question.optionsText), ...(question.type === "match" ? { matches: lines(question.matchesText) } : {}), answer: question.type === "choice" ? question.answerText.trim() : question.answerText.split("|").map(item => item.trim()).filter(Boolean), explanation: question.explanation.trim(), ...(question.visual ? { visual: question.visual } : {}), ...(question.audioText ? { audioText: question.audioText } : {}), ...(question.worldId ? { worldId: question.worldId } : {}) }));
    const sameItems = (left: string[], right: string[]) => left.length === right.length && [...left].sort().every((item, index) => item === [...right].sort()[index]);
    const invalid = questions.some(question => {
      if (!question.prompt || question.options.length < 2 || !question.answer.length || !question.explanation) return true;
      if (question.type === "choice") return typeof question.answer !== "string" || !question.options.includes(question.answer);
      if (!Array.isArray(question.answer)) return true;
      if (question.type === "order") return !sameItems(question.answer, question.options);
      if (question.type === "multi") return new Set(question.options).size !== question.options.length || new Set(question.answer).size !== question.answer.length || question.answer.some(answer => !question.options.includes(answer));
      const matches = question.matches || [];
      return matches.length !== question.options.length || new Set(matches).size !== matches.length || new Set(question.options).size !== question.options.length || !sameItems(question.answer, matches);
    });
    if (!draft.title.trim() || !draft.skill.trim() || invalid) { setError("Preencha título, habilidade e cada desafio. Revise o gabarito: ordene todas as opções, marque as respostas corretas ou associe cada item a um par diferente."); return; }
    if (!Number.isInteger(draft.durationMinutes) || draft.durationMinutes < 1 || draft.durationMinutes > 30 || !Number.isInteger(draft.xp) || draft.xp < 10 || draft.xp > 100) { setError("Use uma duração de 1 a 30 minutos e uma recompensa de 10 a 100 XP."); return; }
    if (questions.length > 20 || questions.some(question => question.options.length > 8)) { setError("Inclua até 20 desafios, com 2 a 8 opções em cada um."); return; }
    const result = await execute({ action: "saveActivity", activity: { ...draft, questions, type: questions[0].type, status: "draft" } }, "Rascunho salvo. Você pode revisá-lo e publicar na biblioteca."); if (result) setModal(null);
  }
  function exportCsv() { const rows: (string | number)[][] = [["Estudante", "Turma", "Atividade", "Habilidade", "Data", "Acertos", "Questões", "Aproveitamento (%)", "Tempo (segundos)", "XP"]]; for (const row of recent) { const student = data.students.find(item => item.id === row.studentId); rows.push([student?.name || "", student?.classroomName || "", activityTitle(row.activityId), activityById.get(row.activityId)?.skill || "Diagnóstico", new Date(row.completedAt).toLocaleString("pt-BR"), row.correct, row.total, row.score, row.durationSeconds, row.xpEarned]); } const blob = new Blob(["\ufeff" + rows.map(row => row.map(csvCell).join(";")).join("\r\n")], { type: "text/csv;charset=utf-8;" }); const href = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = href; link.download = `letria-relatorio-${new Date().toISOString().slice(0, 10)}.csv`; link.click(); URL.revokeObjectURL(href); }
  function scopeFilters() { return <div className="ed-scope"><label className="ed-select-label"><Users size={16} /><select aria-label="Filtrar por turma" value={classId} onChange={event => changeClass(event.target.value)}><option value="">Todas as turmas</option>{data.classrooms.map(classroom => <option key={classroom.id} value={classroom.id}>{classroom.name}</option>)}</select></label>{section === "reports" && <label className="ed-select-label"><GraduationCap size={16} /><select aria-label="Filtrar por estudante" value={studentId} onChange={event => { setStudentId(event.target.value); setReportNote(""); }}><option value="">Todos os estudantes</option>{data.students.filter(student => !classId || student.classroomId === classId).map(student => <option key={student.id} value={student.id}>{student.name}</option>)}</select></label>}</div>; }
  function stats() { return <div className="ed-stats"><div className="panel ed-stat"><span className="ed-stat-icon lilac"><Users size={19} /></span><span>Estudantes acompanhados</span><strong>{filteredStudents.length}<small>{activeLearners} com atividades</small></strong></div><div className="panel ed-stat"><span className="ed-stat-icon mint"><ClipboardCheck size={19} /></span><span>Missões concluídas</span><strong>{scopedSubmissions.length}<small>{successful} com 80% ou mais</small></strong></div><div className="panel ed-stat"><span className="ed-stat-icon yellow"><Target size={19} /></span><span>Aproveitamento médio</span><strong>{percent(scopedAverage)}<small>{scopedSubmissions.length ? "Todas as tentativas registradas" : "Aguardando primeiras missões"}</small></strong></div><div className="panel ed-stat"><span className="ed-stat-icon peach"><Sparkles size={19} /></span><span>Precisam de um incentivo</span><strong>{pendingLearners.length}<small>Habilidades que pedem retomada</small></strong></div></div>; }
  function matrix() { return <div className="ed-table-wrap"><table className="ed-table ed-matrix"><thead><tr><th>Estudante</th>{worlds.map(world => <th key={world.id} title={world.title}>Mundo {world.id}</th>)}<th>Geral</th></tr></thead><tbody>{filteredStudents.map(student => <tr key={student.id}><td><span className="ed-name"><span className="ed-avatar">{avatar(student)}</span><span>{student.name}<small>{student.classroomName || "Sem turma"}</small></span></span></td>{worlds.map(world => { const status = getWorldStatus(progressByStudent.get(student.id)!, world.id); const value = status.sampleSize ? status.accuracy : null; return <td key={world.id}><span title={`${world.title}: ${status.sampleSize} questões distintas, ${status.activitiesPracticed} atividades. ${status.reason}`} className={`ed-score ${!status.sampleSize ? "empty" : status.mastered ? "good" : status.status === "review" ? "attention" : "medium"}`}>{status.mastered && <Check size={10} />}{percent(value)}</span><small className="ed-evidence-count">{status.sampleSize ? `${status.sampleSize} questões` : "Sem prática"}</small></td>; })}<td><strong>{percent(average(studentRows(student.id)))}</strong></td></tr>)}</tbody></table>{!filteredStudents.length && <Empty title="Ainda não há alunos neste acompanhamento" text="Confira a turma selecionada ou adicione os alunos em “Turmas e alunos”.">{onNavigate && <button className="btn btn-secondary" onClick={() => onNavigate("classes")}>Ver turmas e alunos<ArrowRight size={16} /></button>}</Empty>}</div>; }
  function diagnosticReport(student: Student) { const result = getDiagnosticResult(progressByStudent.get(student.id)!); return <section className="panel ed-diagnostic-report"><div className="ed-panel-title"><div><h2>O ponto de partida de {student.name.split(" ")[0]}</h2><p>Sondagem inicial · {result.complete ? "Concluída" : result.answered ? "Em andamento" : "Ainda não realizada"}</p></div><Target size={22} /></div>{result.answered ? <><div className="ed-diagnostic-skills">{result.evidence.map(item => <div key={item.worldId}><span>{item.skill}</span><strong>{item.correct}/{item.total || item.expected}</strong><small>{!item.total ? "Sem respostas" : item.correct === item.expected ? "Sinais iniciais de compreensão" : "Explorar com apoio"}</small></div>)}</div><div className="ed-report-method"><strong>Foco inicial sugerido: {worldName(result.suggestedWorldId)}</strong><p>{result.note} Revise esta indicação a partir da observação e das produções da criança.</p></div></> : <div className="ed-report-method"><p>A sondagem fica disponível na jornada do estudante. Seus resultados ajudam a planejar as primeiras intervenções.</p></div>}</section>; }
  function recentTable(limit?: number) { return <div className="ed-table-wrap"><table className="ed-table"><thead><tr><th>Estudante</th><th>Missão</th><th>Resultado</th><th>Data</th></tr></thead><tbody>{recent.slice(0, limit).map(row => { const student = data.students.find(item => item.id === row.studentId); return <tr key={row.id}><td><span className="ed-name"><span className="ed-avatar">{student ? avatar(student) : "🌟"}</span>{student?.name || "Estudante"}</span></td><td>{activityTitle(row.activityId)}<small>{row.correct} de {row.total} questões · {Math.max(1, Math.round(row.durationSeconds / 60))} min</small></td><td><span className={`ed-score ${row.score >= 80 ? "good" : "medium"}`}>{row.score}%</span></td><td className="ed-muted">{date(row.completedAt)}</td></tr>; })}</tbody></table>{!recent.length && <Empty title="As respostas aparecerão aqui" text="Depois de concluir uma atividade, o aluno terá suas respostas registradas neste acompanhamento.">{onNavigate && <button className="btn btn-secondary" onClick={() => onNavigate(data.students.length ? "activities" : "classes")}>{data.students.length ? "Escolher atividades" : "Organizar turma"}<ArrowRight size={16} /></button>}</Empty>}</div>; }
  const titles: Record<string, [string, string]> = {
    dashboard: ["Início", "Veja o próximo passo para preparar as atividades e acompanhar sua turma."],
    classes: ["Turmas e alunos", "Crie uma turma, adicione os alunos e entregue os códigos de entrada."],
    activities: ["Escolher atividades", "Veja uma atividade pronta e escolha uma turma para realizá-la."],
    reports: ["Acompanhar alunos", "Escolha uma turma ou um aluno para entender as respostas e planejar o apoio."],
    family: ["Acompanhar criança", "Entenda as descobertas da criança e encontre uma ideia simples para ajudar em casa."],
    admin: ["Contas da escola", "Cadastre professores e responsáveis e confira quem acompanha cada turma."],
    messages: ["Avisos e orientações", "Leia os avisos da plataforma e as orientações compartilhadas pela escola."],
  };
  const heading = titles[section] || titles.dashboard;
  const child = data.students.find(student => student.id === studentId) || data.students.find(student => student.id === data.session.studentId) || data.students[0];
  const childRows = child ? studentRows(child.id) : [];
  const childNotes = child ? data.notes.filter(note => note.studentId === child.id && note.type === "intervention").sort((a, b) => b.createdAt.localeCompare(a.createdAt)) : [];
  const childLatest = [...childRows].sort((a, b) => b.completedAt.localeCompare(a.completedAt))[0];
  return <div className={`educator ed-section-${section}`}>
    <div className="ed-heading"><div><span className="eyebrow">{isGuardian ? "ESCOLA + FAMÍLIA" : "ESPAÇO DO EDUCADOR"}</span><h1>{heading[0]}</h1><p>{heading[1]}</p></div>{section === "dashboard" && scopeFilters()}{section === "classes" && <button className="btn btn-primary" onClick={() => open({ kind: "class" })}><Plus size={17} /> Nova turma</button>}{section === "activities" && <button className="btn btn-secondary" onClick={() => editActivity()}><Plus size={17} /> Criar atividade</button>}</div>
    {message && <div className="ed-feedback success" role="status"><Check size={18} />{message}<button aria-label="Fechar confirmação" onClick={() => setMessage("")}><X size={16} /></button></div>}{error && !modal && <div className="ed-feedback error" role="alert">{error}<button aria-label="Fechar erro" onClick={() => setError("")}><X size={16} /></button></div>}
    {section === "dashboard" && <>
      {journeyPanel()}
      <details className="ed-dashboard-details panel"><summary><span><strong>Resumo de aprendizagem</strong><small>Veja os resultados, as últimas atividades e quem pode precisar de apoio.</small></span><ChevronRight size={20} /></summary><div className="ed-dashboard-detail-content">
      {stats()}
      <div className="ed-dashboard-grid"><section className="panel ed-evidence"><div className="ed-panel-title"><div><h2>Mapa de aprendizagem</h2><p>Cada cor, uma oportunidade de apoiar.</p></div><span className="ed-caption">POR MUNDO</span></div>{matrix()}<div className="ed-legend"><span><i className="good" />Domínio evidenciado</span><span><i className="medium" />Em descoberta</span><span><i className="attention" />Retomada sugerida</span><span><i className="empty" />Sem prática</span></div></section><aside className="panel ed-attention"><div className="ed-panel-title"><div><span className="ed-small-icon"><Heart size={18} /></span><h2>Um olhar mais atento</h2><p>Sugestões para sua avaliação.</p></div></div>{pendingLearners.slice(0, 3).map(({ student, rows, reviewWorld }) => { const suggestion = `Retomar ${reviewWorld?.skill || "as habilidades do diagnóstico"} com apoio individual e leitura das instruções em voz alta.`; return <div className="ed-intervention" key={student.id}><div className="ed-name"><span className="ed-avatar">{avatar(student)}</span><strong>{student.name}</strong><span className="ed-mini-score">{average(rows)}%</span></div><p>{suggestion}</p><button className="ed-text-button" onClick={() => open({ kind: "note", studentId: student.id, intervention: true, initial: suggestion })}>Revisar intervenção <ArrowRight size={14} /></button></div>; })}{!pendingLearners.length && <div className="ed-small-empty"><span>🌱</span><h3>{scopedSubmissions.length ? "Cada um no seu caminho" : "Vamos conhecer sua turma?"}</h3><p>{scopedSubmissions.length ? "Nenhum estudante com indicação de retomada nas habilidades já praticadas." : "As sugestões aparecem a partir das atividades realizadas."}</p></div>}<p className="ed-disclaimer">Sugestões por regras de desempenho. A decisão pedagógica é sempre sua.</p></aside></div>
      <section className="panel"><div className="ed-panel-title"><div><h2>As últimas descobertas</h2><p>Atividades e conquistas registradas na plataforma.</p></div><span className="badge">{scopedSubmissions.length} registros</span></div>{recentTable(5)}</section>
      </div></details>
    </>}
    {section === "classes" && <>
      <div className="ed-section-guide"><BookOpen size={21} aria-hidden="true" /><div><strong>1. Crie a turma. 2. Adicione os alunos. 3. Entregue os códigos.</strong><p>O código aparece ao cadastrar cada aluno. Para trocar um código depois, use “Novo código”.</p></div></div>
      <div className="ed-class-grid">{data.classrooms.map((classroom, index) => { const learners = data.students.filter(student => student.classroomId === classroom.id); const rows = data.submissions.filter(row => learners.some(student => student.id === row.studentId)); return <article key={classroom.id} className={`panel ed-class-card ${classId === classroom.id ? "selected" : ""}`}><div className="ed-class-card-top"><span className={`ed-class-icon color-${index % 3}`}><GraduationCap size={25} /></span><div className="ed-inline-actions"><button aria-label={`Editar ${classroom.name}`} onClick={() => open({ kind: "class", id: classroom.id })}><Pencil size={15} /></button><button aria-label={`Excluir ${classroom.name}`} onClick={() => open({ kind: "confirm", title: "Excluir turma?", text: "A turma será removida. Os estudantes continuarão cadastrados sem vínculo com essa turma.", action: { action: "deleteClassroom", id: classroom.id } })}><Trash2 size={15} /></button></div></div><h2>{classroom.name}</h2><p>{classroom.grade} · {classroom.teacherName}</p><div className="ed-class-numbers"><span><Users size={15} />{learners.length} exploradores</span><strong>{percent(average(rows))}</strong></div><ProgressBar value={average(rows) || 0} /><button className="ed-class-open" onClick={() => changeClass(classroom.id === classId ? "" : classroom.id)}>{classId === classroom.id ? "Mostrando esta turma" : "Ver alunos desta turma"}<ChevronRight size={16} /></button></article>; })}<button className="ed-new-class" onClick={() => open({ kind: "class" })}><span><Plus size={25} /></span><strong>Criar turma</strong><small>Informe o nome e o ano escolar</small></button></div>
      <section className="panel"><div className="ed-panel-title"><div><h2>{selectedClass?.name || "Todos os estudantes"}</h2><p>{filteredStudents.length} exploradores prontos para aprender.</p></div><div className="ed-tools">{scopeFilters()}<button className="btn btn-secondary" onClick={() => open({ kind: "student", classId })}><Plus size={16} /> Adicionar aluno</button></div></div><div className="ed-table-wrap"><table className="ed-table"><thead><tr><th>Estudante</th><th>Turma</th><th>Missões</th><th>Aproveitamento</th><th>Ações</th></tr></thead><tbody>{filteredStudents.map(student => <tr key={student.id}><td><span className="ed-name"><span className="ed-avatar">{avatar(student)}</span><strong>{student.name}</strong></span></td><td>{student.classroomName || "Sem turma"}</td><td>{studentRows(student.id).length}</td><td>{percent(average(studentRows(student.id)))}</td><td><div className="ed-inline-actions ed-student-actions"><button disabled={busy} aria-label={`Gerar novo código de ${student.name}`} onClick={() => open({ kind: "replace-code", studentId: student.id })}><KeyRound size={17} />Novo código</button><button aria-label={`Editar ${student.name}`} onClick={() => open({ kind: "student", id: student.id })}><Pencil size={16} />Editar</button><button aria-label={`Registrar observação de ${student.name}`} onClick={() => open({ kind: "note", studentId: student.id })}><MessageCircle size={17} />Anotar</button><button aria-label={`Excluir ${student.name}`} onClick={() => open({ kind: "confirm", title: "Excluir estudante?", text: `O cadastro de ${student.name} e seu histórico de aprendizagem serão excluídos. Esta ação não pode ser desfeita.`, action: { action: "deleteStudent", id: student.id } })}><Trash2 size={16} /></button></div></td></tr>)}</tbody></table>{!filteredStudents.length && <Empty icon={<Users size={28} />} title="Adicione o primeiro aluno" text="Ao salvar o cadastro, você recebe um código para ele entrar na plataforma."><button className="btn btn-primary" onClick={() => open(data.classrooms.length ? { kind: "student", classId } : { kind: "class" })}><Plus size={16} />{data.classrooms.length ? "Adicionar aluno" : "Criar turma"}</button></Empty>}</div></section>
      <section className="panel"><div className="ed-panel-title"><div><h2>Atividades da turma</h2><p>Estas propostas aparecem para os alunos em “Atividades da turma”.</p></div><button className="btn btn-secondary" onClick={() => open(data.classrooms.length ? { kind: "assign" } : { kind: "class" })}><Plus size={16} /> Enviar atividade</button></div>{data.assignments.filter(assignment => !classId || assignment.classroomId === classId).map(assignment => <div key={assignment.id} className="ed-assignment"><span className="ed-stat-icon lilac"><BookOpen size={19} /></span><div><strong>{assignment.title || activityTitle(assignment.activityId)}</strong><small>{data.classrooms.find(item => item.id === assignment.classroomId)?.name || "Turma"} · {assignment.dueDate ? `Até ${date(assignment.dueDate + "T12:00:00")}` : "Sem prazo"}</small></div><button aria-label={`Remover missão ${assignment.title}`} className="ed-icon-button" onClick={() => open({ kind: "confirm", title: "Remover missão da turma?", text: "A proposta será removida. As atividades já realizadas permanecem no histórico.", action: { action: "deleteAssignment", id: assignment.id } })}><Trash2 size={17} /></button></div>)}{!data.assignments.filter(assignment => !classId || assignment.classroomId === classId).length && <Empty title="Escolha uma atividade para a turma" text="Abra as atividades prontas, confira uma proposta e use o botão “Propor”."><button className="btn btn-secondary" onClick={() => followJourney(data.classrooms.length ? { kind: "navigate", section: "activities" } : { kind: "class" })}>{data.classrooms.length ? "Escolher atividades" : "Criar turma"}<ArrowRight size={16} /></button></Empty>}</section>
    </>}
    {section === "activities" && <><div className="ed-section-guide"><BookOpen size={21} aria-hidden="true" /><div><strong>Escolha, confira e envie para a turma.</strong><p>Use os filtros para encontrar uma atividade. “Explorar” abre a atividade para você conhecer; “Propor” permite escolher a turma e o prazo.</p></div></div>{!data.classrooms.length && <div className="ed-prerequisite"><p>Para enviar uma atividade aos alunos, primeiro crie uma turma. Você já pode explorar o banco.</p><button className="btn btn-secondary" onClick={() => open({ kind: "class" })}><Plus size={16} />Criar turma</button></div>}<ActivityBank activities={allActivities} customActivities={data.customActivities} favorites={favorites} busy={busy} onFavorite={toggleFavorite} onPlay={onPlay} onAssign={activity => open(data.classrooms.length ? { kind: "assign", activityId: activity.id } : { kind: "class" })} onEdit={activity => editActivity(activity)} onCopy={activity => editActivity(activity, true)} onPublish={activity => { void execute({ action: "publishActivity", id: activity.id }, "Atividade publicada! Agora ela pode ser atribuída às turmas."); }} onDelete={activity => open({ kind: "confirm", title: "Excluir atividade?", text: "Atividades com resultados de estudantes são preservadas e não podem ser excluídas. Se ainda não houver resultados, a atividade e suas atribuições serão removidas.", action: { action: "deleteActivity", id: activity.id } })} /></>}
    {section === "reports" && <>
      <div className="ed-report-tools">{scopeFilters()}<div className="ed-tools"><button disabled={!recent.length} className="btn btn-secondary" onClick={exportCsv}><Download size={16} />Exportar CSV</button><button className="btn btn-primary" onClick={() => window.print()}><FileText size={16} />Imprimir / PDF</button></div></div>
      <div className="ed-report-document"><div className="ed-report-print-heading"><strong>letria · Relatório de aprendizagem</strong><span>{data.session.institutionName} · {new Date().toLocaleDateString("pt-BR")}{data.session.isDemo ? " · Dados fictícios de demonstração" : ""}</span></div>{stats()}{selectedStudent && diagnosticReport(selectedStudent)}<section className="panel"><div className="ed-panel-title"><div><h2>{selectedStudent ? `A jornada de ${selectedStudent.name}` : selectedClass ? `A jornada da ${selectedClass.name}` : "Visão de aprendizagem"}</h2><p>Aproveitamento calculado a partir de todas as tentativas do recorte.</p></div><span className="badge"><Target size={13} />EVIDÊNCIAS</span></div>{matrix()}<div className="ed-report-method"><strong>Como ler este relatório</strong><p>A matriz usa a última resposta de cada questão distinta do catálogo da trilha. O domínio exige pelo menos 10 questões, duas atividades, 80% de acertos e no máximo um erro nas cinco respostas mais recentes. “—” indica ausência de prática. O diagnóstico orienta o início, sem liberar mundos. As médias gerais e a tabela de evidências incluem todas as tentativas e atividades autorais. Esses registros apoiam a avaliação do educador.</p></div></section><section className="panel"><div className="ed-panel-title"><div><h2>Evidências da jornada</h2><p>Resultados, atividades e datas para apoiar seu acompanhamento.</p></div></div>{recentTable()}</section><section className="panel ed-narrative"><div className="ed-panel-title"><div><h2>Parecer do educador</h2><p>Seu olhar dá significado aos números. Este parecer é privado da equipe pedagógica.</p></div><Pencil size={20} /></div>{selectedStudent ? <><textarea aria-label="Parecer do educador" value={reportNote} onChange={event => setReportNote(event.target.value)} placeholder={`Descreva as conquistas de ${selectedStudent.name.split(" ")[0]}, os apoios necessários e os próximos passos...`} rows={5} /><button className="btn btn-primary ed-no-print" disabled={busy || !reportNote.trim()} onClick={async () => { const result = await execute({ action: "addNote", studentId: selectedStudent.id, text: reportNote.trim(), type: "observation" }, "Parecer salvo no histórico do estudante."); if (result) setReportNote(""); }}><Check size={16} />Salvar parecer</button></> : <p className="ed-muted ed-narrative-hint">Selecione um estudante no filtro acima para escrever um parecer individual.</p>}{data.notes.filter(note => filteredStudents.some(student => student.id === note.studentId)).map(note => <div className="ed-note" key={note.id}><strong>{data.students.find(student => student.id === note.studentId)?.name}<span>{date(note.createdAt)} · {note.author}</span></strong><p>{note.text}</p><span className="badge">{note.type === "intervention" ? "Intervenção" : "Observação"}</span></div>)}</section></div>
    </>}
    {section === "reports" && <section className="panel ed-recordings-panel"><div className="ed-panel-title"><div><h2>Leituras para acompanhar</h2><p>Ouça as gravações autorizadas e registre suas observações no histórico do estudante.</p></div><Volume2 size={22} /></div><div className="ed-recording-list">{data.recordings.filter(recording => filteredStudents.some(student => student.id === recording.studentId)).map(recording => { const learner = data.students.find(student => student.id === recording.studentId)!; return <div className="ed-assignment ed-recording" key={recording.id}><span className="ed-avatar">{avatar(learner)}</span><div><strong>{learner.name}</strong><small>{activityTitle(recording.activityId)} · {date(recording.createdAt)}</small></div><audio controls preload="none" aria-label={`Leitura de ${learner.name}: ${activityTitle(recording.activityId)}`} src={`/api/audio?id=${encodeURIComponent(recording.id)}`} /><button className="ed-text-button" onClick={() => open({ kind: "note", studentId: learner.id, initial: `Leitura de “${activityTitle(recording.activityId)}” (${date(recording.createdAt)}): ` })}><Pencil size={15} />Registrar avaliação</button></div>; })}</div>{!data.recordings.some(recording => filteredStudents.some(student => student.id === recording.studentId)) && <Empty icon={<Volume2 size={26} />} title="As vozes dessa jornada" text="As leituras gravadas com autorização da família aparecerão aqui, conforme os filtros selecionados." />}</section>}
    {section === "family" && (child ? <>
      {data.students.length > 1 && <label className="ed-child-picker">Qual criança você quer acompanhar?<select value={child.id} onChange={event => setStudentId(event.target.value)}>{data.students.map(student => <option key={student.id} value={student.id}>{student.name}</option>)}</select></label>}
      <section className="ed-family-welcome panel"><span className="ed-family-avatar" aria-hidden="true">{avatar(child)}</span><div><span className="eyebrow">ESCOLA E FAMÍLIA, JUNTAS</span><h2>Acompanhamento de {child.name.split(" ")[0]}</h2><p>{child.classroomName || "Ainda sem turma vinculada"} · Cada criança aprende no seu ritmo.</p></div></section>
      <div className="ed-family-grid">
        <section className="panel ed-family-overview"><div className="ed-panel-title"><div><h2>Como está aprendendo</h2><p>{childRows.length ? `${childRows.length} atividades realizadas até agora.` : "A primeira atividade será o começo deste acompanhamento."}</p></div><BookOpen size={23} /></div>
          <p className="ed-family-latest">{childLatest ? <>Na última atividade, <strong>{activityTitle(childLatest.activityId)}</strong>, {child.name.split(" ")[0]} respondeu {childLatest.correct} de {childLatest.total} desafios corretamente. A atividade foi realizada em {date(childLatest.completedAt)}.</> : <>Quando {child.name.split(" ")[0]} concluir uma atividade, você verá aqui o que praticou. A escola entrega o código para a criança entrar.</>}</p>
          <p className="ed-family-reading-note">As respostas mostram o que a criança já praticou e onde pode precisar de ajuda. Uma atividade sozinha não define sua aprendizagem.</p>
          <a className="btn btn-primary" href="#ed-family-help">Ver como ajudar hoje<ArrowRight size={16} /></a>
          <details className="ed-family-progress-details"><summary>Ver habilidades praticadas<ChevronRight size={18} /></summary><div className="ed-world-progress">{worlds.map(world => { const status = getWorldStatus(progressByStudent.get(child.id)!, world.id); return <div key={world.id}><div><strong>{world.title}</strong><span>{status.mastered ? "Aprendizagem observada nas atividades" : status.sampleSize ? `${status.sampleSize} desafios praticados · ${status.accuracy}% de acertos` : "Ainda não praticado"}</span></div><ProgressBar value={status.accuracy} mint /></div>; })}</div><p className="ed-family-reading-note">Estes registros ajudam na conversa com o professor. A avaliação considera também as atividades e observações feitas na escola.</p></details>
        </section>
        <aside className="panel ed-family-notes"><div className="ed-panel-title"><div><h2>Orientações da escola</h2><p>Leia o que o professor sugeriu para {child.name.split(" ")[0]}.</p></div><Heart size={21} /></div>{childNotes.length ? childNotes.slice(0, 4).map(note => <div className="ed-note" key={note.id}><strong>{note.author}<span>{date(note.createdAt)}</span></strong><p>{note.text}</p></div>) : <Empty icon={<MessageCircle size={25} />} title="Ainda não há orientações" text="As sugestões compartilhadas pelo professor aparecerão aqui. Enquanto isso, experimente a brincadeira abaixo com a criança." />}{onNavigate && childNotes.length > 4 && <button className="ed-text-button" onClick={() => onNavigate("messages")}>Ver todas as orientações<ArrowRight size={15} /></button>}</aside>
      </div>
      <section className="panel ed-family-home-action" id="ed-family-help" tabIndex={-1}><span className="ed-stat-icon yellow" aria-hidden="true"><Sparkles size={23} /></span><div><span className="eyebrow">COMO AJUDAR HOJE</span><h2>Uma brincadeira com as palavras da casa</h2><p>Separem alguns minutos, sem pressa. Você só precisa de um objeto e da companhia da criança.</p><ol><li>Peça que a criança escolha um objeto da casa.</li><li>Falem o nome dele devagar e escutem o primeiro som.</li><li>Pensem juntos em outra palavra que comece com esse som.</li></ol><p className="ed-family-reading-note">Valorize a tentativa. Se estiver difícil, dê um exemplo e descubram juntos.</p></div></section>
      <section className="panel ed-consent"><div><span className="ed-stat-icon mint"><ShieldCheck size={22} /></span><div><h2>Permissão para usar a voz</h2><p>Você escolhe se a criança pode usar o microfone e gravar leituras. A autorização é opcional e pode ser retirada a qualquer momento. Sem ela, a criança continua com as atividades e conversa com a Lumi por texto.</p></div></div><label className="ed-switch"><input aria-label={`Autorizar uso da voz de ${child.name}`} type="checkbox" checked={child.consentAudio} disabled={busy} onChange={event => execute({ action: "setConsent", studentId: child.id, consent: event.target.checked }, "Preferência de gravação atualizada.")} /><span /><strong>{child.consentAudio ? "Uso da voz autorizado" : "Uso da voz desativado"}</strong></label></section>
      {data.recordings.filter(recording => recording.studentId === child.id).length > 0 && <section className="panel"><div className="ed-panel-title"><h2>Gravações de leitura</h2><span className="ed-muted">Você pode ouvir ou excluir cada gravação.</span></div>{data.recordings.filter(recording => recording.studentId === child.id).map(recording => <div className="ed-assignment" key={recording.id}><Volume2 size={21} /><div><strong>{activityTitle(recording.activityId)}</strong><small>{date(recording.createdAt)}</small></div><a className="btn btn-secondary" href={`/api/audio?id=${encodeURIComponent(recording.id)}`} target="_blank" rel="noreferrer">Ouvir gravação</a><button className="ed-icon-button" aria-label={`Excluir gravação de ${activityTitle(recording.activityId)}`} onClick={() => open({ kind: "confirm", title: "Excluir gravação?", text: "O arquivo de áudio será excluído permanentemente.", action: { action: "deleteRecording", id: recording.id } })}><Trash2 size={17} /></button></div>)}</section>}
    </> : <Empty title="Sua conta precisa ser vinculada à criança" text="Peça à escola para vincular seu acesso ao cadastro da criança. Depois disso, as atividades e orientações aparecerão aqui." />)}

    {section === "admin" && <>{journeyPanel()}<div className="ed-admin-grid"><section className="panel ed-institution"><span className="ed-stat-icon lilac"><GraduationCap size={27} /></span><span className="eyebrow">SUA INSTITUIÇÃO</span><h2>{data.session.institutionName}</h2><p>Um espaço para transformar descobertas em aprendizagem.</p><div className="ed-institution-stats"><span><strong>{data.classrooms.length}</strong>turmas</span><span><strong>{data.students.length}</strong>estudantes</span><span><strong>{data.customActivities.length}</strong>criações</span></div><span className="badge"><ShieldCheck size={13} />{data.session.isDemo ? "Ambiente de demonstração" : "Ambiente autenticado"}</span></section><section className="panel"><div className="ed-panel-title"><div><h2>Acesso de educadores e famílias</h2><p>Cada pessoa, com o acesso de que precisa.</p></div><button className="btn btn-primary" onClick={() => open({ kind: "account" })}><Plus size={16} />Criar acesso</button></div><div className="ed-role-card"><span className="ed-stat-icon lilac"><GraduationCap size={20} /></span><div><strong>Educador</strong><p>Turmas, atividades, intervenções e relatórios.</p></div><span className="badge">Pedagógico</span></div><div className="ed-role-card"><span className="ed-stat-icon peach"><Heart size={20} /></span><div><strong>Responsável</strong><p>Progresso do estudante vinculado e consentimento de voz.</p></div><span className="badge">Acompanhamento</span></div><div className="ed-role-card"><span className="ed-stat-icon mint"><ShieldCheck size={20} /></span><div><strong>Administrador</strong><p>Gestão da instituição e criação de acessos.</p></div><span className="badge">Gestão</span></div></section></div><section className="panel"><div className="ed-panel-title"><div><h2>Pessoas conectadas</h2><p>Acessos cadastrados na sua instituição.</p></div><span className="badge">{data.staff.length} contas</span></div><div className="ed-table-wrap"><table className="ed-table"><thead><tr><th>Pessoa</th><th>Perfil</th><th>Vínculo</th></tr></thead><tbody>{data.staff.map(person => <tr key={person.id}><td><strong>{person.name}</strong><small>{person.email || "Conta de demonstração"}</small></td><td>{person.role === "admin" ? "Administrador" : person.role === "teacher" ? "Educador" : "Responsável"}</td><td>{person.role === "guardian" ? data.students.find(student => student.id === person.studentId)?.name || "Sem estudante vinculado" : person.role === "teacher" ? data.classrooms.filter(classroom => classroom.teacherUserId === person.id).map(classroom => classroom.name).join(", ") || "Sem turma atribuída" : "Gestão da instituição"}</td></tr>)}</tbody></table></div>{data.session.isDemo && <p className="ed-report-method ed-muted">Este ambiente usa pessoas fictícias. Para cadastrar acessos reais, crie sua instituição pelo menu da conta.</p>}</section><section className="panel"><div className="ed-panel-title"><div><h2>Uma experiência para cada pessoa</h2><p>Preferências de acessibilidade e conforto desta conta.</p></div><Sparkles size={22} /></div><div className="ed-setting-row"><div><strong>Sons da experiência</strong><p>Efeitos sonoros durante as atividades.</p></div><label className="ed-switch"><input aria-label="Sons da experiência" type="checkbox" checked={data.settings.sound} disabled={busy} onChange={event => execute({ action: "saveSettings", sound: event.target.checked }, "Preferências atualizadas.")} /><span /></label></div><div className="ed-setting-row"><div><strong>Reduzir movimento</strong><p>Uma navegação com menos animações.</p></div><label className="ed-switch"><input aria-label="Reduzir movimento" type="checkbox" checked={data.settings.reducedMotion} disabled={busy} onChange={event => execute({ action: "saveSettings", reducedMotion: event.target.checked }, "Preferências atualizadas.")} /><span /></label></div><div className="ed-setting-row"><div><strong>Tamanho do texto</strong><p>Escolha o tamanho mais confortável.</p></div><select className="ed-filter" aria-label="Tamanho do texto" value={data.settings.fontScale} disabled={busy} onChange={event => execute({ action: "saveSettings", fontScale: Number(event.target.value) }, "Preferências atualizadas.")}><option value={1}>Padrão</option><option value={1.15}>Ampliado</option><option value={1.3}>Extra ampliado</option></select></div></section><section className="panel"><div className="ed-panel-title"><div><h2>Consentimento de gravação</h2><p>As autorizações são gerenciadas pelas famílias e pela escola.</p></div><ShieldCheck size={22} /></div><div className="ed-table-wrap"><table className="ed-table"><thead><tr><th>Estudante</th><th>Turma</th><th>Gravação de voz</th></tr></thead><tbody>{data.students.map(student => <tr key={student.id}><td>{student.name}</td><td>{student.classroomName || "Sem turma"}</td><td><span className={`ed-score ${student.consentAudio ? "good" : "empty"}`}>{student.consentAudio ? "Autorizada" : "Desativada"}</span></td></tr>)}</tbody></table></div></section></>}
    {section === "messages" && <div className="ed-message-grid"><section className="panel"><div className="ed-panel-title"><div><h2>O que há de novo</h2><p>Atualizações da plataforma.</p></div><button className="ed-text-button" disabled={busy || !data.notifications.some(item => !item.read)} onClick={() => execute({ action: "readNotifications" }, "Notificações marcadas como lidas.")}><CheckCheck size={16} />Marcar como lidas</button></div>{data.notifications.map(notification => <article key={notification.id} className={`ed-notification ${notification.read ? "" : "unread"}`}><span className="ed-stat-icon lilac"><Sparkles size={19} /></span><div><h3>{notification.title}</h3><p>{notification.text}</p><small>{date(notification.createdAt)}</small></div>{!notification.read && <span className="ed-unread-dot" />}</article>)}{!data.notifications.length && <Empty title="Tudo em dia por aqui" text="Novas atualizações aparecerão neste espaço." />}</section><section className="panel"><div className="ed-panel-title"><div><h2>Mural de acompanhamento</h2><p>Registros e orientações para acompanhar cada estudante.</p></div></div>{!isGuardian && <form className="ed-wall-form" onSubmit={async event => { event.preventDefault(); const formElement = event.currentTarget; const form = new FormData(formElement); const result = await execute({ action: "addNote", studentId: field(form, "studentId"), text: field(form, "text"), type: "intervention" }, "Orientação compartilhada com a família."); if (result) formElement.reset(); }}><label>Para a família de<select required name="studentId" defaultValue=""><option value="" disabled>Selecione o estudante</option>{data.students.map(student => <option key={student.id} value={student.id}>{student.name}</option>)}</select></label><textarea name="text" aria-label="Orientação para a família" required minLength={3} rows={3} placeholder="Compartilhe uma descoberta ou uma orientação para aprender em casa..." /><button className="btn btn-primary" disabled={busy || !data.students.length}><MessageCircle size={16} />Compartilhar orientação</button></form>}{data.notes.map(note => <div className="ed-note" key={note.id}><strong>{data.students.find(student => student.id === note.studentId)?.name || "Estudante"}<span>{date(note.createdAt)}</span></strong><p>{note.text}</p><small>{note.author} · {note.type === "intervention" ? "Orientação compartilhada" : "Observação privada"}</small></div>)}{!data.notes.length && <Empty title="A conversa começa com uma descoberta" text="As orientações compartilhadas aparecerão também no acompanhamento da família. Observações privadas ficam apenas com a equipe pedagógica." />}</section></div>}
    {modal && <div className="ed-modal-backdrop" onMouseDown={event => { if (event.target === event.currentTarget && !busy) setModal(null); }}><div className={`ed-modal ${modal.kind === "editor" ? "ed-modal-wide" : ""}`} role="dialog" aria-modal="true" aria-labelledby="ed-dialog-title" ref={dialogRef}><button className="ed-modal-close" aria-label="Fechar janela" disabled={busy} onClick={() => setModal(null)}><X size={21} /></button>
      <span className="eyebrow">CADA DETALHE FAZ DIFERENÇA</span><h2 id="ed-dialog-title">{modal.kind === "class" ? modal.id ? "Editar turma" : "Criar turma" : modal.kind === "student" ? modal.id ? "Editar estudante" : "Adicionar aluno" : modal.kind === "assign" ? "Enviar atividade para a turma" : modal.kind === "note" ? modal.intervention ? "Seu olhar sobre a intervenção" : "Registrar uma descoberta" : modal.kind === "account" ? "Criar conta de professor ou responsável" : modal.kind === "replace-code" ? "Gerar novo código de entrada?" : modal.kind === "editor" ? draft.id ? "Aprimorar sua atividade" : "Sua ideia vira uma missão" : modal.title}</h2>
      {error && <div className="ed-feedback error" role="alert">{error}</div>}
      {modal.kind === "confirm" ? <><p className="ed-modal-description">{modal.text}</p><div className="ed-form-actions"><button className="btn btn-secondary" disabled={busy} onClick={() => setModal(null)}>Cancelar</button><button className="btn ed-btn-danger" disabled={busy} onClick={async () => { const result = await execute(modal.action, "Registro removido."); if (result) setModal(null); }}>{busy ? "Excluindo..." : "Confirmar exclusão"}</button></div></> : modal.kind === "replace-code" ? <><p className="ed-modal-description">O código atual de <strong>{data.students.find(student => student.id === modal.studentId)?.name}</strong> deixará de funcionar. Um novo código será mostrado para você entregar ao aluno.</p><p className="ed-muted">Use esta opção quando o código anterior foi perdido ou precisa ser trocado.</p><div className="ed-form-actions"><button className="btn btn-secondary" disabled={busy} onClick={() => setModal(null)}>Manter código atual</button><button className="btn btn-primary" disabled={busy} onClick={() => { const learner = data.students.find(student => student.id === modal.studentId); if (learner) void accessCode(learner); }}><KeyRound size={17} />{busy ? "Gerando..." : "Gerar novo código"}</button></div></> : modal.kind === "code" ? <><p className="ed-modal-description">Copie ou anote este código e entregue ao aluno. Na tela de entrada, ele deve escolher “Sou estudante” e digitar o código. Guarde-o agora: ele não será exibido novamente.</p><div className="ed-access-code">{modal.code}</div><p className="ed-muted">Um código novo substitui o anterior.</p><button className="btn btn-primary" onClick={async () => { try { await navigator.clipboard.writeText(modal.code); setMessage("Código copiado."); } catch { setError("Não foi possível copiar automaticamente. Selecione o código acima e copie."); } }}><Copy size={17} />Copiar código</button><button className="btn btn-secondary ed-code-done" onClick={() => setModal(null)}>Concluir<Check size={17} /></button></> : modal.kind === "editor" ? <div className="ed-editor"><div className="ed-tabs"><button className={!previewEditor ? "active" : ""} onClick={() => setPreviewEditor(false)}><Pencil size={15} />Editar atividade</button><button className={previewEditor ? "active" : ""} onClick={() => setPreviewEditor(true)}><Eye size={15} />Pré-visualizar</button></div>{!previewEditor ? <><div className="ed-form-grid"><label className="ed-span-full">Título da missão<input maxLength={100} value={draft.title} onChange={event => setDraft({ ...draft, title: event.target.value })} placeholder="Ex.: Os sons do meu jardim" /></label><label className="ed-span-full">Descrição<textarea rows={2} value={draft.description} onChange={event => setDraft({ ...draft, description: event.target.value })} placeholder="O que o estudante vai descobrir?" /></label><label>Mundo<select value={draft.worldId} onChange={event => setDraft({ ...draft, worldId: Number(event.target.value) })}>{worlds.map(world => <option key={world.id} value={world.id}>{world.title}</option>)}</select></label><label>Habilidade<input value={draft.skill} onChange={event => setDraft({ ...draft, skill: event.target.value })} /></label><label>Duração estimada (min)<input type="number" min={1} max={30} value={draft.durationMinutes} onChange={event => setDraft({ ...draft, durationMinutes: Number(event.target.value) })} /></label><label>XP da missão<input type="number" min={10} max={100} step={5} value={draft.xp} onChange={event => setDraft({ ...draft, xp: Number(event.target.value) })} /></label></div>{draft.questions.map((question, index) => { const update = (patch: Partial<DraftQuestion>) => setDraft({ ...draft, questions: draft.questions.map((item, itemIndex) => itemIndex === index ? { ...item, ...patch } : item) }); return <div key={question.id} className="ed-question-editor"><div className="ed-question-heading"><strong>Desafio {index + 1}</strong>{draft.questions.length > 1 && <button className="ed-icon-button" aria-label={`Remover desafio ${index + 1}`} onClick={() => setDraft({ ...draft, questions: draft.questions.filter((_, itemIndex) => itemIndex !== index) })}><Trash2 size={16} /></button>}</div><div className="ed-form-grid"><label>Tipo de desafio<select value={question.type} onChange={event => update({ type: event.target.value as Question["type"], answerText: "" })}><option value="choice">Escolher uma resposta</option><option value="order">Colocar em ordem</option><option value="multi">Selecionar várias respostas</option><option value="match">Associar pares</option></select></label><label>Palavra ou texto de apoio<textarea rows={3} value={question.stimulus} onChange={event => update({ stimulus: event.target.value })} placeholder="Ex.: BORBOLETA" /></label><label className="ed-span-full">Enunciado<textarea rows={2} value={question.prompt} onChange={event => update({ prompt: event.target.value })} placeholder="Ex.: Com qual letra começa BORBOLETA?" /></label><label>{question.type === "match" ? "Coluna esquerda — um item por linha" : "Opções — uma por linha"}<textarea rows={4} value={question.optionsText} onChange={event => update({ optionsText: event.target.value })} placeholder={"B\nP\nD"} /></label><QuestionAnswerEditor question={question} onChange={update} /><label className="ed-span-full">Explicação e dica pedagógica<textarea rows={2} value={question.explanation} onChange={event => update({ explanation: event.target.value })} placeholder="Uma explicação acolhedora para ajudar a criança a aprender." /></label></div></div>; })}<button className="btn btn-secondary" disabled={draft.questions.length >= 20} onClick={() => setDraft({ ...draft, questions: [...draft.questions, blankQuestion()] })}><Plus size={16} />Adicionar desafio</button></> : <div className="ed-editor-preview"><span className="badge">PRÉVIA PARA REVISÃO</span><h3>{draft.title || "Título da sua missão"}</h3><p>{draft.description}</p>{draft.questions.map((question, index) => <div className="ed-preview-question" key={question.id}><span>DESAFIO {index + 1}</span><h4>{question.prompt || "Enunciado do desafio"}</h4>{question.visual && <span className="bank-question-visual" aria-hidden="true">{question.visual}</span>}{question.stimulus && <div className="ed-preview-stimulus">{question.stimulus}</div>}<div className="ed-preview-options">{question.optionsText.split("\n").filter(Boolean).map((option, optionIndex) => <span key={optionIndex}>{option}</span>)}</div>{question.type === "match" && <div className="ed-preview-options">{lines(question.matchesText).map((item, index) => <span key={index}>{item}</span>)}</div>}<small>{question.type === "match" ? lines(question.optionsText).map((item, index) => `${item} → ${question.answerText.split("|")[index]?.trim() || "Não definido"}`).join("; ") : `Resposta: ${question.answerText || "Não definida"}`}</small><p>{question.explanation || "Inclua uma explicação pedagógica."}</p></div>)}</div>}<div className="ed-editor-footer"><p>Ao salvar, a atividade fica em rascunho para sua revisão antes da publicação.</p><button className="btn btn-primary" disabled={busy} onClick={saveDraft}><Check size={16} />{busy ? "Salvando..." : "Salvar rascunho"}</button></div></div> : <form className="ed-form" onSubmit={submitModal}>
        {modal.kind === "class" && <><label>Nome da turma<input required name="name" maxLength={80} defaultValue={data.classrooms.find(item => item.id === modal.id)?.name || ""} placeholder="Ex.: Exploradores do 1º A" /></label><label>Ano / etapa<select required name="grade" defaultValue={data.classrooms.find(item => item.id === modal.id)?.grade || "1º ano"}><option>Educação infantil</option><option>1º ano</option><option>2º ano</option><option>3º ano</option><option>4º ano</option><option>5º ano</option><option>EJA</option><option>Outra etapa</option></select></label>{data.session.role === "admin" && <label>Educador responsável<select name="teacherUserId" defaultValue={data.classrooms.find(item => item.id === modal.id)?.teacherUserId || ""}><option value="">Sem educador atribuído</option>{data.staff.filter(person => person.role === "teacher").map(person => <option key={person.id} value={person.id}>{person.name}</option>)}</select><span className="ed-muted">O educador terá acesso somente às turmas sob sua responsabilidade. Crie o acesso em Contas da escola se ele ainda não estiver listado.</span></label>}</>}
        {modal.kind === "student" && <><label>Nome do estudante<input name="name" required maxLength={100} defaultValue={data.students.find(item => item.id === modal.id)?.name || ""} placeholder="Nome e sobrenome" /></label><div className="ed-form-grid"><label>Turma<select name="classroomId" defaultValue={data.students.find(item => item.id === modal.id)?.classroomId || modal.classId || ""}><option value="">Sem turma</option>{data.classrooms.map(classroom => <option key={classroom.id} value={classroom.id}>{classroom.name}</option>)}</select></label><label>Ano / etapa<input name="grade" defaultValue={data.students.find(item => item.id === modal.id)?.grade || "1º ano"} /></label></div><label>Companheiro de aventura<select name="avatar" defaultValue={data.students.find(item => item.id === modal.id)?.avatar || "🦊"}><option value="🦊">🦊 Raposa</option><option value="🐼">🐼 Panda</option><option value="🐸">🐸 Sapinho</option><option value="🦁">🦁 Leão</option><option value="🐱">🐱 Gatinho</option><option value="🐰">🐰 Coelho</option><option value="🦉">🦉 Coruja</option></select></label>{!modal.id && <p className="ed-muted">O código de acesso será gerado após o cadastro. Não é necessário e-mail para o estudante.</p>}</>}
        {modal.kind === "assign" && <><label>Atividade<select name="activityId" required defaultValue={modal.activityId || ""}><option value="" disabled>Escolha uma atividade</option>{allActivities.filter(activity => !data.customActivities.some(custom => custom.id === activity.id && custom.status === "draft")).map(activity => <option key={activity.id} value={activity.id}>{activity.title}</option>)}</select></label><label>Turma<select name="classroomId" required defaultValue={classId || ""}><option value="" disabled>Selecione a turma</option>{data.classrooms.map(classroom => <option key={classroom.id} value={classroom.id}>{classroom.name}</option>)}</select></label><label>Nome da proposta (opcional)<input name="title" maxLength={120} placeholder="Ex.: Nossa missão desta semana" /></label><label>Prazo<input required name="dueDate" type="date" min={new Date().toISOString().slice(0, 10)} /></label>{!data.classrooms.length && <p className="ed-warning">Crie uma turma em “Turmas e alunos” antes de enviar uma atividade.</p>}</>}
        {modal.kind === "note" && <><p className="ed-modal-description">Para {data.students.find(student => student.id === modal.studentId)?.name}. {modal.intervention ? "Esta orientação será compartilhada com a família." : "Esta observação é privada e fica disponível somente à equipe pedagógica."}</p><label>{modal.intervention ? "Ajuste a proposta para este estudante" : "Seu registro"}<textarea required name="text" minLength={3} maxLength={3000} rows={6} defaultValue={modal.initial || ""} placeholder="O que você observou? Qual pode ser o próximo passo?" /></label>{modal.intervention && <p className="ed-muted">Revise a sugestão antes de adotá-la. Você pode alterar livremente o texto ou cancelar sem registrar.</p>}</>}
        {modal.kind === "account" && <><label>Nome<input required name="name" maxLength={100} placeholder="Nome completo" /></label><label>E-mail<input required name="email" type="email" autoComplete="off" placeholder="pessoa@escola.com.br" /></label><label>Senha inicial<input required name="password" type="password" autoComplete="new-password" minLength={10} maxLength={128} placeholder="De 10 a 128 caracteres" /></label><label>Quem vai usar esta conta?<select required name="role" value={accountRole} onChange={event => setAccountRole(event.target.value as "teacher" | "guardian")}><option value="teacher">Professor</option><option value="guardian">Responsável pela criança</option></select></label>{accountRole === "guardian" ? <label>Qual criança esta pessoa vai acompanhar?<select required name="studentId" defaultValue=""><option value="" disabled>Escolha a criança</option>{data.students.map(student => <option key={student.id} value={student.id}>{student.name}</option>)}</select><small>O responsável verá apenas os registros da criança vinculada à conta.</small></label> : <p className="ed-muted">Depois de criar a conta, escolha este professor no cadastro da turma, em “Turmas e alunos”.</p>}<p className="ed-muted">Entregue o e-mail e a senha inicial à pessoa para que ela possa entrar.</p></>}
        <div className="ed-form-actions"><button type="button" className="btn btn-secondary" disabled={busy} onClick={() => setModal(null)}>Cancelar</button><button className="btn btn-primary" disabled={busy || (modal.kind === "assign" && !data.classrooms.length)}>{busy ? "Salvando..." : modal.kind === "assign" ? "Enviar para a turma" : modal.kind === "note" && modal.intervention ? "Aprovar e registrar" : "Salvar"}<Check size={16} /></button></div>
      </form>}
    </div></div>}
  </div>;
}
